// Baca CONFIG (key/value) -> objek cfg + gate jam etis WIB + clamp parameter beban
const rows = $input.all().map(i => i.json);
const cfg = {};
for (const r of rows) {
  const k = String(r.key || r.Key || '').trim();
  if (k) cfg[k] = (r.value !== undefined && r.value !== null) ? r.value : ((r.Value !== undefined && r.Value !== null) ? r.Value : '');
}
const num = (k, d) => { const n = Number(cfg[k]); return isNaN(n) ? d : n; };

let templates = [];
try { templates = JSON.parse(cfg.followup_templates || '[]'); } catch (e) { templates = []; }
if (!Array.isArray(templates)) templates = [];

const openH = num('followup_open_hour', 8);
const closeH = num('followup_close_hour', 21);
const wibHour = Number(new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jakarta', hour: '2-digit', hour12: false }).format(new Date()));

// Di luar jam etis atau template kosong -> stop; trigger jam berikutnya coba lagi.
// Kandidat yang "ketinggalan" otomatis terkirim di slot berikutnya (antrian tidak hilang).
if (wibHour < openH || wibHour >= closeH) return [];
if (!templates.length) return [];

// Clamp agar salah konfigurasi tidak berubah jadi blast massal.
let minDelay = num('followup_min_delay_sec', 20);
let maxDelay = num('followup_max_delay_sec', 45);
if (minDelay < 3) minDelay = 3;                    // jaga jarak minimum (anti-spam)
if (maxDelay < minDelay) maxDelay = minDelay + 5;
let maxPerRun = num('followup_max_per_run', 20);
if (maxPerRun < 1) maxPerRun = 1;
if (maxPerRun > 300) maxPerRun = 300;              // plafon keras: 1 run selalu << 1 jam

return [{ json: {
  config: {
    kirimi_user_code: String(cfg.kirimi_user_code || '').trim(),
    kirimi_secret: String(cfg.kirimi_secret || '').trim(),
    kirimi_device_id: String(cfg.kirimi_device_id || '').trim(),
    admin_phone: String(cfg.admin_phone || '').trim(),
    exclude_numbers: [cfg.admin_phone, cfg.admin_phone_display, cfg.field_team_phone, cfg.media_team_phone]
      .map(v => String(v || '').replace(/\D/g, '')).filter(Boolean),
    followup_max: num('followup_max', 0),
    followup_interval_hours: num('followup_interval_hours', 72),
    templates: templates,
    min_delay: minDelay,
    max_delay: maxDelay,
    max_per_run: maxPerRun,
    open_hour: openH,
    close_hour: closeH
  },
  now_epoch: Math.floor(Date.now() / 1000)
} }];

// Saring baris STATS -> user layak follow-up sekarang, lalu BATASI jumlah per-run.
// Cap ini yang bikin workflow sanggup skala besar: 1000 nomor otomatis dicicil lintas jam/hari,
// bukan diblast dalam satu eksekusi.
const base = $('Parse Config FU').first().json;
const cfg = base.config;
const now = base.now_epoch;
const intervalSec = (cfg.followup_interval_hours || 72) * 3600;

// Jam WIB sekarang -> hitung sisa waktu sampai jam tutup (batas aman anti-bleed).
const wibParts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Jakarta', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date());
const wibHour = Number((wibParts.find(p => p.type === 'hour') || {}).value || 0);
const wibMin = Number((wibParts.find(p => p.type === 'minute') || {}).value || 0);

const out = [];
const seen = new Set();

for (const item of $input.all()) {
  const row = item.json;
  const noWa = String(row['No WA'] || '').trim();
  if (!noWa) continue;
  const digits = noWa.replace(/\D/g, '');
  if (!digits) continue;
  if (seen.has(digits)) continue;                              // dedupe kalau STATS ada baris ganda
  if (cfg.exclude_numbers.includes(digits)) continue;          // nomor tim/admin
  if (/^off$/i.test(String(row['bot_mode'] || '').trim())) continue;             // dipegang manusia
  if (/^scheduled$/i.test(String(row['survey_status'] || '').trim())) continue;  // goal tercapai
  if (Number(row['Counter'] || 0) < 1) continue;               // belum pernah chat

  const lastReply = Number(row['last_reply_ts'] || 0);
  if (!lastReply) continue;                                    // belum pernah dibalas bot
  if (now - lastReply < intervalSec) continue;                 // masih hangat, jangan ganggu

  const lastFu = Number(row['last_follow_up_ts'] || 0);
  if (lastFu && now - lastFu < intervalSec) continue;          // belum jatuh tempo follow-up berikutnya

  const fuCount = Number(row['follow_up_count'] || 0);
  if (cfg.followup_max > 0 && fuCount >= cfg.followup_max) continue;  // 0 = tanpa batas

  // Personalisasi: {nama}/{name} -> nama depan (kalau template pakai placeholder).
  // Kalau template polos tanpa placeholder, tidak ada yang berubah (aman).
  const namaRaw = String(row['Nama'] || '').trim();
  const namaFirst = namaRaw ? namaRaw.split(/\s+/)[0] : '';
  let msg = String(cfg.templates[fuCount % cfg.templates.length] || '');
  msg = msg.replace(/\{\s*(nama|name)\s*\}/gi, namaFirst || 'Kak');

  seen.add(digits);
  out.push({ json: {
    no_wa: noWa,
    lid: String(row['lid'] || '').trim(),
    nama: namaRaw,
    follow_up_count: fuCount,
    prev_last_fu: lastFu || '',                                 // untuk rollback kalau kirim gagal
    last_reply_ts: lastReply,
    message: msg
  } });
}

// Prioritas antrian: yang belum pernah di-follow-up dulu, lalu yang paling lama tidak dibalas.
out.sort((a, b) => {
  const af = Number(a.json.follow_up_count), bf = Number(b.json.follow_up_count);
  if (af !== bf) return af - bf;
  return Number(a.json.last_reply_ts) - Number(b.json.last_reply_ts);
});

// Batas per-run = min(cap config, kapasitas waktu tersisa sebelum jam tutup).
const avgDelay = ((cfg.min_delay + cfg.max_delay) / 2) + 2;     // +2s estimasi latency API
const minutesToClose = Math.max(0, (cfg.close_hour - wibHour) * 60 - wibMin);
const capByTime = Math.floor((minutesToClose * 60) / avgDelay);
const cap = Math.max(0, Math.min(cfg.max_per_run, capByTime));

return out.slice(0, cap);
